from collections import Counter
import heapq as hq

def func(nums, k):
    count = Counter()
    for sublist in nums:
        for num in sublist:
            count[num] += 1
    h = []
    for num, freq in count.items():
        if len(h) < k:
            hq.heappush(h, (freq, num))
        elif freq > h[0][0]:
            hq.heappop(h)
            hq.heappush(h, (freq, num))
    return [num for freq, num in sorted(h, reverse=True)]
```

