from collections import defaultdict

def rearange_string(str):
    dict = defaultdict(int)
    for i in range(len(str)):
        dict[str[i]] += 1
    max_char = max(dict, key=dict.get)
    if dict[max_char] > (len(str) + 1) // 2:
        return "Not Possible"
    res = [''] * len(str)
    i = 0
    while dict[max_char] > 0:
        res[i] = max_char
        i += 2
        dict[max_char] -= 1
    for char in dict:
        while dict[char] > 0:
            if i >= len(str):
                i = 1
            res[i] = char
            i += 2
            dict[char] -= 1
    return ''.join(res)
```

