from collections import defaultdict

def rearange_string(s):
    n = len(s)
    frequency = defaultdict(int)
    for char in s:
        frequency[char] += 1

    max_freq = max(frequency.values())
    char_with_max_freq = [char for char, freq in frequency.items() if freq == max_freq]

    if max_freq > (n + 1) // 2:
        return "Not Possible"

    result = [''] * n
    index = 0
    for char in char_with_max_freq:
        for _ in range(max_freq):
            if index >= n:
                index = 1
            result[index] = char
            index += 2

    for char, freq in frequency.items():
        if char not in char_with_max_freq:
            for _ in range(freq):
                if index >= n:
                    index = 1
                result[index] = char
                index += 2

    return ''.join(result)
```

