def is_sublist(list1, list2):
    # Check if list2 is empty, then it's a sublist of any list
    if not list2:
        return True
    # Check if list2 is longer than list1, then it cannot be a sublist
    elif len(list2) > len(list1):
        return False
    # Check each element of list2 in list1
    for i in range(len(list1)):
        if list1[i] == list2[0]:
            n = 1
            # Check subsequent elements
            while (n < len(list2)) and (list1[i+n] == list2[n]):
                n += 1
            # If all elements match, list2 is a sublist
            if n == len(list2):
                return True
    # If no match is found, list2 is not a sublist
    return False
