    elif len(sub_list) > len(main_list):
        return False
    # Iterate through main_list to check for the presence of sub_list
    else:
        for i in range(len(main_list)):
            # If the first element of sub_list matches an element in main_list
            if main_list[i] == sub_list[0]:
                # Check if the rest of sub_list matches the corresponding elements in main_list
                n = 1
                while (n < len(sub_list)) and (main_list[i+n] == sub_list[n]):
                    n += 1
                # If all elements of sub_list match, return True
                if n == len(sub_list):
                    return True
    # If no match is found, return False
    return False
