def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while gap > 1 or sorted:
        if gap > 1:
            gap = int(gap / shrink_factor)

        sorted = True
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr
```

