def extract_missing(ranges, start, end):
    missing_ranges = []
    current_start = start

    for r in sorted(ranges):
        if r[0] > current_start:
            missing_ranges.append((current_start, r[0]))
        current_start = max(current_start, r[1])

    if current_start < end:
        missing_ranges.append((current_start, end))

    return missing_ranges
```

```python
def extract_missing(input_list, start_range, end_range):
    # Initialize the result list with the start and end range
    result = [(start_range, end_range)]
    # Iterate through each range in the input list
    for s, e in input_list:
        # If the current range starts after the current result range ends, add the gap
        if s > result[-1][1]:
            result.append((result[-1][1], s))
        # If the current range ends after the current result range starts, update the result range
        if e > result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], e))
    # Iterate through the result list to fix any overlapping ranges
    for i in range(len(result) - 1, 0, -1):
        if result[i][0] <= result[i - 1][1]:
            result[i - 1] = (result[i - 1][0], max(result[i - 1][1], result[i][1]))
            result.pop(i)
    # Return the cleaned result list
