def search(arr, n):
    low = 0
    high = n - 1
    while low <= high:
        mid = low + (high - low) // 2
        if (mid == 0 or arr[mid - 1] != arr[mid]) and (mid == n - 1 or arr[mid + 1] != arr[mid]):
            return arr[mid]
        elif (mid % 2 == 0 and arr[mid] == arr[mid + 1]) or (mid % 2 == 1 and arr[mid] == arr[mid - 1]):
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

