    if b < 0:
        return -multiply_int(a, -b)
    # Base case: if b is 0, the product is 0
    elif b == 0:
        return 0
    # Base case: if b is 1, the product is a
    elif b == 1:
        return a
    # Recursive case: add a to the product of a and b-1
    else:
        return a + multiply_int(a, b - 1)
