```python
def flip(arr, i):
    start = 0
    while start < i:
        arr[start], arr[i] = arr[i], arr[start]
        start += 1
        i -= 1

def find_max_index(arr, n):
    max_index = 0
    for i in range(1, n):
        if arr[i] > arr[max_index]:
            max_index = i
    return max_index

def pancake_sort(arr):
    arr_len = len(arr)
    while arr_len > 1:
        max_index = find_max_index(arr, arr_len)
        if max_index != arr_len - 1:
            flip(arr, max_index)
            flip(arr, arr_len - 1)
        arr_len -= 1
    return arr
```

