def sum_digits_twoparts(N): 
    if (N < 10): 
        return N 
    else: 
        res = 0
        while (N > 0): 
            res += N % 10
            N = N // 10
        return res 
```

```python
def sum_digits_twoparts(N): 
    part1 = 0
    part2 = N 
    for i in range(N // 2, -1, -1): 
        if (i * 2 == N): 
            continue
        part1 = i 
        part2 = N - i 
        break
    return sum(int(digit) for digit in str(part1)) + sum(int(digit) for digit in str(part2))
```

```python
def sum_digits_twoparts(N): 
    if N <= 10: 
        return N 
    half = N // 2
    return sum(map(int, str(half))) + sum(map(int, str(N - half)))
```

```python
def sum_digits_twoparts(n):
    if n < 10:
        return n
    sum_digits = 0
    while n > 0:
        sum_digits += n % 10
        n //= 10
    return sum_digits
```

