def min_Ops(arr, n, k): 
    arr.sort() 
    if (arr[n - 1] - arr[0] < k): 
        return -1
    low = 0
    high = arr[n - 1] - arr[0] 
    while (low < high): 
        mid = (low + high) // 2
        if (check(mid, arr, n, k)): 
            high = mid 
        else: 
            low = mid + 1
    return low 

def check(mid, arr, n, k): 
    operations = 0
    for i in range(n): 
        if (arr[i] + mid < arr[n - 1]): 
            operations += (arr[n - 1] - arr[i] - mid) 
    return (operations % k == 0)
```

