def min_Ops(arr,n,k): 
    arr.sort() 
    sum = 0
    for i in range(n): 
        sum += arr[i] 
    avg = sum // k 
    if (sum % k != 0): 
        return -1
    count = 0
    for i in range(n): 
        if (arr[i] < avg): 
            count += avg - arr[i] 
    return count 
