```python
def answer(l, r):
    # If double the lower limit is within the range, return the pair (l, 2*l)
    if (2 * l <= r):
        return (l, 2 * l)
    # If double the lower limit minus one is within the range, return the pair (l, 2*l - 1)
    elif (2 * l - 1 <= r):
        return (l, 2 * l - 1)
    # If no such pair exists, return -1
    else:
        return -1
```

