def common_prefix(arr, n):
    if n == 0:
        return ""
    if n == 1:
        return arr[0]

    first = arr[0]
    for i in range(1, n):
        second = arr[i]
        j = 0
        while j < len(first) and j < len(second) and first[j] == second[j]:
            j += 1
        first = first[:j]

    return first
```

