def find_longest_repeating_subseq(s): 
    n = len(s) 
    dp = [[0 for x in range(n + 1)] for y in range(n + 1)] 
    for i in range(1, n + 1): 
        for j in range(1, n + 1): 
            if s[i - 1] == s[j - 1] and i != j: 
                dp[i][j] = 1 + dp[i - 1][j - 1] 
            else: 
                dp[i][j] = max(dp[i][j - 1], dp[i - 1][j]) 
    return dp[n][n]
```

