def min_Operations(x, y): 
    if (x > y): 
        x, y = y, x 
    diff = y - x 
    count = 0
    while (diff): 
        if (diff % 2 == 0): 
            diff /= 2
        else: 
            diff -= 1
        count += 1
    return count
