def max_sum(triangle, n):
    # If the triangle has only one row, return the value of that row
    if n == 1:
        return triangle[0][0]
    # Update the second row based on the first row
    triangle[1][0] += triangle[0][0]
    triangle[1][1] += triangle[0][0]
    # Iterate over the rows starting from the third row
    for i in range(2, n):
        # Update the first and last elements of the current row
        triangle[i][0] += triangle[i-1][0]
        triangle[i][i] += triangle[i-1][i-1]
        # Update the intermediate elements of the current row
        for j in range(1, i):
            if triangle[i][j] + triangle[i-1][j-1] > triangle[i][j] + triangle[i-1][j]:
                triangle[i][j] += triangle[i-1][j-1]
            else:
                triangle[i][j] += triangle[i-1][j]
    # Return the maximum sum found in the last row
    return max(triangle[n-1])
```

