def get_total_number_of_sequences(n, m): 
    mod = 1000000007
    dp = [[0 for i in range(m + 1)] for i in range(n + 1)] 
    for i in range(1, m + 1): 
        dp[1][i] = i 
    for i in range(2, n + 1): 
