def get_total_number_of_sequences(m, n): 
    memo = [[0 for _ in range(n + 1)] for _ in range(m + 1)] 
    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0 or j == 0: 
                memo[i][j] = 0
            elif i < j: 
                memo[i][j] = 0
            elif j == 1: 
                memo[i][j] = i 
            else: 
                memo[i][j] = memo[i - 1][j] + memo[i // 2][j - 1] 
    return memo[m][n]
