    res = []
    for ele, val in test_list:
        if ele not in [x[0] for x in res]:
            res.append((ele, val, ele, 1))
        else:
            for idx in range(len(res)):
                if res[idx][0] == ele:
                    res[idx] = (ele, val, res[idx][2], res[idx][3] + 1)
    res.sort(key=lambda x: x[3], reverse=True)
    return res
