def sort_on_occurence(lst):
    # Create a dictionary to count occurrences of the first element of each tuple
    count_dict = {}
    for key, *values in lst:
        if key in count_dict:
            count_dict[key] += 1
        else:
            count_dict[key] = 1

    # Sort the list based on the count of the first element in descending order
    sorted_list = sorted(lst, key=lambda x: count_dict[x[0]], reverse=True)

    # Create a new list with the count of occurrences appended to each tuple
    result = []
    for key, *values in sorted_list:
        result.append((key, *values, count_dict[key]))

    return result
```

