def max_sum(arr, n):
    # Initialize a list to store the maximum sum of increasing subsequence ending at each index
    msis = arr[:]

    # Calculate maximum sum of increasing subsequence for each element
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and msis[i] < msis[j] + arr[i]:
                msis[i] = msis[j] + arr[i]

    # Initialize a list to store the maximum sum of decreasing subsequence starting at each index
    msds = arr[:]

    # Calculate maximum sum of decreasing subsequence for each element
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and msds[i] < msds[j] + arr[i]:
                msds[i] = msds[j] + arr[i]

    # Calculate the maximum sum of bi-tonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, msis[i] + msds[i] - arr[i])

    return max_sum
```

