def max_sum(arr, n):
    # Initialize up array where up[i] stores the maximum sum of increasing subsequence ending at index i
    up = [arr[i] for i in range(n)]

    # Initialize down array where down[i] stores the maximum sum of decreasing subsequence starting at index i
    down = [arr[i] for i in range(n)]

    # Fill up array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and up[i] < up[j] + arr[i]:
                up[i] = up[j] + arr[i]

    # Fill down array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and down[i] < down[j] + arr[i]:
                down[i] = down[j] + arr[i]

    # Calculate maximum sum of bi-tonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, up[i] + down[i] - arr[i])

    return max_sum
