        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def newman_shanks_williams(p):
        if p == 1:
            return 2
        result = 2
        for i in range(2, p + 1):
            result = (result * result + 1) % (2**i - 1)
        return result

    count = 0
    num = 2
    while True:
        if is_prime(num):
            nsw_value = newman_shanks_williams(num)
            if is_prime(nsw_value):
                count += 1
                if count == n:
                    return nsw_value
        num += 1
