def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    same, diff = k, k * (k - 1)
    total = same + diff
    for _ in range(3, n + 1):
        same, diff = diff, total * (k - 1)
        total = (same + diff) % 1000000007
    return total
```

