def sum_div(n):
    # Initialize sum of divisors
    sum = 1
    # Loop through possible divisors
    i = 2
    while i * i <= n:
        # If i is a divisor of n
        if n % i:
            i += 1
        else:
            # If divisors are equal, add it once
            if i * (n // i) == n:
                sum = sum + i + n//i
            else:
                # Add both divisors
                sum = sum + i + n//i
            i += 1
    return sum
```

