def count_binary_seq(n):
    def binomial_coefficient(n, k):
        result = 1
        if k > n - k:
            k = n - k
        for i in range(k):
            result *= (n - i)
            result //= (i + 1)
        return result

    def count_sequences(n):
        sum = 0
        for i in range(n + 1):
            sum += binomial_coefficient(n, i) ** 2
        return sum

    return count_sequences(n) * 2
```

