def count_binary_seq(n):
    def binomialCoeff(n, k):
        res = 1
        if k > n - k:
            k = n - k
        for i in range(k):
            res *= (n - i)
            res //= (i + 1)
        return res

    def countSeqUtil(n, count1, count2):
        if n == 0:
            return 1 if count1 == count2 else 0
        return (countSeqUtil(n - 1, count1 + 1, count2) +
                countSeqUtil(n - 1, count1, count2 + 1))

    return 2 * countSeqUtil(n, 0, 0)
```

