def count_binary_seq(n):
    mod = 10**9 + 7
    c = [[0 for _ in range(2 * n + 1)] for _ in range(2 * n + 1)]
    c[0][0] = 1
    for i in range(2 * n):
        for j in range(min(i + 1, 2 * n)):
            c[i + 1][j] = (c[i][j] + c[i][j - 1]) % mod
            if j + 1 <= 2 * n:
                c[i + 1][j + 1] = (c[i + 1][j + 1] + c[i][j]) % mod
    res = 0
    for i in range(n + 1):
        res = (res + c[n][i] * c[n][i]) % mod
    return res
```

