def max_sum_increasing_subseq(arr, n, i, k):
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for ind in range(n):
        dp[ind][ind] = arr[ind]

    for ind in range(n):
        for prev in range(ind):
            if arr[ind] > arr[prev]:
                dp[ind][ind] = max(dp[ind][ind], dp[prev][ind] + arr[ind])

    max_sum = 0
    for ind in range(n):
        if arr[k] > arr[ind]:
            max_sum = max(max_sum, dp[ind][k] + arr[k])

    return max_sum
```

