        return 0
    if n == 1:
        return max(grid[0][0], grid[1][0])

    include = max(grid[0][0], grid[1][0])
    exclude = 0

    for i in range(1, n):
        new_exclude = max(exclude, include)
        include = exclude + max(grid[0][i], grid[1][i])
        exclude = new_exclude

    return max(include, exclude)
