from itertools import groupby

def modified_encode(data):
    def encode_group(group):
        if len(list(group)) > 1:
            return [len(list(group)), next(group)]
        return next(group)

    if isinstance(data, list):
        return [encode_group(group) for _, group in groupby(data)]
    else:
        return ''.join([encode_group(group) for _, group in groupby(data)])
