def max_volume(S): 
    max_vol = 0
    for i in range(1, S // 3 + 1): 
        for j in range(1, S // 2 + 1): 
            k = S - i - j 
            if k > 0: 
                max_vol = max(max_vol, i * j * k) 
    return max_vol
