def find_demlo(s):
    # Initialize an empty list to store the Demlo number
    res = []
    # Append increasing digits from 1 to the length of the input string
    for i in range(1, len(s) + 1):
        res.append(str(i))
    # Append decreasing digits from the second last to 1
    for i in range(len(s) - 1, 0, -1):
        res.append(str(i))
    # Join the list into a single string and return
    return ''.join(res)
```

