def re_arrange(arr, n):
    def rotate_right(arr, start, end):
        temp = arr[end]
        for i in range(end, start, -1):
            arr[i] = arr[i - 1]
        arr[start] = temp

    i = 0
    while i < n:
        if i % 2 == 0 and arr[i] < 0:
            j = i + 1
            while j < n and arr[j] < 0:
                j += 1
            if j < n:
                rotate_right(arr, i, j)
                j += 1
        elif i % 2 == 1 and arr[i] >= 0:
            j = i + 1
            while j < n and arr[j] >= 0:
                j += 1
            if j < n:
                rotate_right(arr, i, j)
                j += 1
        i += 1
    return arr
