def re_arrange(arr, n):
    i, j, temp = 0, 1, 0
    while True:
        while i < n and arr[i] >= 0:
            i += 2
        while j < n and arr[j] < 0:
            j += 2
        if i < n and j < n:
            temp = arr[j]
            for k in range(j, i, -1):
                arr[k] = arr[k - 1]
            arr[i] = temp
            i += 2
            j += 2
        else:
            break
    return arr
