def sum_of_alternates(test_tup):
    # Initialize sums for alternate chains
    res1, res2 = 0, 0
    # Iterate through the tuple elements
    for idx, ele in enumerate(test_tup):
        # Add to the first sum if the index is even
        if idx % 2 == 0:
            res1 += ele
        # Add to the second sum if the index is odd
        else:
            res2 += ele
    # Return the sums as a tuple
    return (res1, res2)
