def find_minimum_range(arrays):
    max_value = float('-inf')
    min_range = float('inf')
    position = [0] * len(arrays)

    while True:
        min_value = float('inf')
        for i in range(len(arrays)):
            if position[i] == len(arrays[i]):
                return (min_range, max_value)
            min_value = min(min_value, arrays[i][position[i]])

        if max_value < min_value:
            min_range = max_value
            max_value = min_value

        for i in range(len(arrays)):
            if arrays[i][position[i]] == min_value:
                position[i] += 1
```

