import heapq

def find_minimum_range(arrays):
    max_val = float('-inf')
    min_heap = []
    for arr in arrays:
        heapq.heappush(min_heap, (arr[0], arr, 1))
        max_val = max(max_val, arr[0])

    min_range = float('inf')
    while len(min_heap) == len(arrays):
        min_val, arr, idx = heapq.heappop(min_heap)
        if max_val - min_val < min_range:
            min_range = max_val - min_val

        if idx < len(arr):
            heapq.heappush(min_heap, (arr[idx], arr, idx + 1))
            max_val = max(max_val, arr[idx])

    return (min_val, min_val + min_range)
```

