from heapq import merge

def find_minimum_range(arrays):
    merged = merge(*arrays)
    min_range = float('inf')
    current_max = float('-inf')
    start = end = None

    for num in merged:
        current_max = max(current_max, num)
        if end is not None:
            min_range = min(min_range, current_max - arrays[0][end])
        end += 1

        if end >= len(arrays[0]):
            break

    return (end - min_range, end - 1)
```

