def find_ways(N): 
    table = [[0 for x in range(N + 1)] for y in range(N + 1)] 
    for i in range(N + 1): 
        for j in range(N + 1): 
            if i == 0 and j == 0: 
                table[i][j] = 1
            elif i == 0: 
                table[i][j] = 0
            elif j == 0: 
                table[i][j] = 1
            else: 
                table[i][j] = table[i - 1][j] + table[i][j - 1] 
    return table[N][N] 
```

