def find_lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        lucas_prev = 2
        lucas_curr = 1
        for _ in range(2, n + 1):
            lucas_next = lucas_prev + lucas_curr
            lucas_prev = lucas_curr
            lucas_curr = lucas_next
        return lucas_curr
