def get_max_sum(n):
    dp = [0] * (n + 1)
    def dfs(x):
        if x <= 1:
            return x
        if dp[x] != 0:
            return dp[x]
        dp[x] = max(dfs(x // 2) + dfs(x // 3) + dfs(x // 4) + dfs(x // 5), x)
        return dp[x]
    return dfs(n)
```

