def ncr_modp(n, r, p): 
    C = [0 for i in range(r + 1)] 
    C[0] = 1
    for i in range(1, n + 1): 
        for j in range(min(i, r), 0, -1): 
            C[j] = (C[j] + C[j - 1]) % p 
    return C[r]
```

```python
def ncr_modp(n, r, p): 
    if r > n: 
        return 0
    c = [0 for i in range(r+1)] 
    c[0] = 1
    for i in range(1, n+1): 
        j = min(i, r) 
        while (j > 0): 
            c[j] = (c[j] + c[j-1]) % p 
            j -= 1
    return c[r]
```

