import heapq

def k_smallest_pairs(nums1, nums2, k):
    min_heap = []
    for num1 in nums1:
        for num2 in nums2:
            if len(min_heap) < k:
                heapq.heappush(min_heap, (num1 + num2, [num1, num2]))
            elif num1 + num2 < min_heap[0][0]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, (num1 + num2, [num1, num2]))
    return [pair for _, pair in min_heap]
