def k_smallest_pairs(arr1, arr2, k):
    from heapq import heapify, heappop
    heap = []
    for i in arr1:
        for j in arr2:
            if len(heap) < k:
                heappush(heap, (i + j, i, j))
            else:
                if i + j < heap[0][0]:
                    heappop(heap)
                    heappush(heap, (i + j, i, j))
                else:
                    break
    return [(i, j) for _, i, j in heap]
