def k_smallest_pairs(nums1, nums2, k):
    from heapq import heapify, heappop
    pairs = []
    heapify(pairs)
    for i in nums1:
        for j in nums2:
            if len(pairs) < k:
                heappush(pairs, (i + j, [i, j]))
            elif i + j < pairs[0][0]:
                heappop(pairs)
                heappush(pairs, (i + j, [i, j]))
            else:
                break
    return [pair[1] for pair in pairs]
