def cal_sum(n): 
    if (n <= 0): 
        return 0
    if (n == 1): 
        return 2
    if (n == 2): 
        return 5
    F = [0] * (n + 1) 
    F[0] = 3
    F[1] = 0
    F[2] = 2
    for i in range(3, n + 1): 
        F[i] = F[i - 2] + F[i - 3] 
    return sum(F)
