def sumofFactors(n): 
    result = 1
    for i in range(2, int(n**0.5) + 1): 
        count = 0
        curr_sum = 1
        curr_term = 1
        while (n % i == 0): 
            count += 1
            n //= i 
            if (count % 2 == 1): 
                curr_sum = curr_sum + i 
            else: 
                curr_sum = curr_sum - i 
            curr_term = curr_term * i 
        result *= curr_sum  
    if (n >= 2): 
        result *= (1 + n) 
    return result 
```

