def max_profit(price, k):
    n = len(price)
    profit = [[0 for x in range(k + 1)] for x in range(n)]
    for i in range(1, n):
        for j in range(1, k + 1):
            max_diff = -price[0]
            for l in range(i):
                max_diff = max(max_diff, profit[l][j - 1] - price[l])
            profit[i][j] = max(profit[i - 1][j], price[i] + max_diff)
    return profit[n - 1][k]
```

