```python
def binomial_probability(n, k, p):
    def factorial(x):
        if x == 0:
            return 1
        else:
            return x * factorial(x-1)

    binom_coeff = factorial(n) / (factorial(k) * factorial(n - k))
    probability = binom_coeff * (p ** k) * ((1 - p) ** (n - k))
    return probability
```

